 36	import org.slf4j.LoggerFactory;
 37	
 38	import org.apache.hadoop.thirdparty.com.google.common.annotations.VisibleForTesting;
 39	
 40	class VEDeviceDiscoverer {
 41	  private static final String STATE_TERMINATING = "TERMINATING";
 42	  private static final String STATE_INITIALIZING = "INITIALIZING";
 43	  private static final String STATE_OFFLINE = "OFFLINE";
 44	  private static final String STATE_ONLINE = "ONLINE";
 45	  private static final Logger LOG =
 46	      LoggerFactory.getLogger(VEDeviceDiscoverer.class);
 47	
 48	  private static final String[] DEVICE_STATE = {STATE_ONLINE, STATE_OFFLINE,
 49	      STATE_INITIALIZING, STATE_TERMINATING};
 50	
 51	  private UdevUtil udev;
 52	  private Function<String[], CommandExecutor>
 53	      commandExecutorProvider = this::createCommandExecutor;
 54	
 55	  VEDeviceDiscoverer(UdevUtil udevUtil) {
 56	    udev = udevUtil;
 57	  }
 58	
 59	  public Set<Device> getDevicesFromPath(String path) throws IOException {
 60	    MutableInt counter = new MutableInt(0);
 61	
 62	    return Files.walk(Paths.get(path), 1)
 63	      .filter(p -> p.toFile().getName().startsWith("veslot"))
 64	      .map(p -> toDevice(p, counter))
 65	      .collect(Collectors.toSet());
 66	  }
 67	
 68	  private Device toDevice(Path p, MutableInt counter) {
 69	    CommandExecutor executor =
 70	        commandExecutorProvider.apply(
 71	            new String[]{"stat", "-L", "-c", "%t:%T:%F", p.toString()});
 72	
 73	    try {
 74	      LOG.info("Checking device file: {}", p);
 75	      executor.execute();
 76	      String statOutput = executor.getOutput();
 77	      String[] stat = statOutput.trim().split(":");
 78	
 79	      int major = Integer.parseInt(stat[0], 16);
 80	      int minor = Integer.parseInt(stat[1], 16);
 81	      char devType = getDevType(p, stat[2]);
 82	      int deviceNumber = makeDev(major, minor);
 83	      LOG.info("Device: major: {}, minor: {}, devNo: {}, type: {}",
 84	          major, minor, deviceNumber, devType);
 85	      String sysPath = udev.getSysPath(deviceNumber, devType);
 86	      LOG.info("Device syspath: {}", sysPath);
 87	      String deviceState = getDeviceState(sysPath);
 88	
 89	      Device.Builder builder = Device.Builder.newInstance();
 90	      builder.setId(counter.getAndIncrement())
 91	        .setMajorNumber(major)
 92	        .setMinorNumber(minor)
 93	        .setHealthy(STATE_ONLINE.equalsIgnoreCase(deviceState))
 94	        .setStatus(deviceState)
 95	        .setDevPath(p.toAbsolutePath().toString());
 96	
 97	      return builder.build();
 98	    } catch (IOException e) {
 99	      throw new UncheckedIOException("Cannot execute stat command", e);
100	    }
101	  }
102	
103	  private int makeDev(int major, int minor) {
104	    return major * 256 + minor;
105	  }
106	
107	  private char getDevType(Path p, String fromStat) {
108	    if (fromStat.contains("character")) {
109	      return 'c';
110	    } else if (fromStat.contains("block")) {
111	      return 'b';
112	    } else {
113	      throw new IllegalArgumentException(
114	          "File is neither a char nor block device: " + p);
115	    }
116	  }
117	
118	  private String getDeviceState(String sysPath) throws IOException {
119	    Path statePath = Paths.get(sysPath, "os_state");
120	
121	    try (FileInputStream fis =
122	        new FileInputStream(statePath.toString())) {
123	      byte state = (byte) fis.read();
124	
125	      if (state < 0 || DEVICE_STATE.length <= state) {
126	        return String.format("Unknown (%d)", state);
127	      } else {
128	        return DEVICE_STATE[state];
129	      }
130	    }
131	  }
132	
133	  private CommandExecutor createCommandExecutor(String[] command) {
134	    return new Shell.ShellCommandExecutor(
135	        command);
136	  }
137	
138	  @VisibleForTesting
139	  void setCommandExecutorProvider(
140	      Function<String[], CommandExecutor> provider) {
141	    this.commandExecutorProvider = provider;
142	  }
143	}

